Here is a shunting-yard infix evaluator with two real bugs. Reproduce both with failing pytest tests FIRST, then fix the code and show all tests passing.

def evaluate(expr):
    import re
    tokens = re.findall(r"\d+\.?\d*|[+\-*/^()]", expr)
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    out, ops = [], []
    def apply(op):
        b, a = out.pop(), out.pop()
        out.append({'+': a+b, '-': a-b, '*': a*b, '/': a/b, '^': a**b}[op])
    for t in tokens:
        if t[0].isdigit():
            out.append(float(t))
        elif t == '(':
            ops.append(t)
        elif t == ')':
            while ops[-1] != '(':
                apply(ops.pop())
            ops.pop()
        else:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[t]:
                apply(ops.pop())
            ops.append(t)
    while ops:
        apply(ops.pop())
    return out[0]

Bug 1: right-associativity of ^ is wrong (2^3^2 should be 512, not 64). Bug 2: unary minus is not handled at all (-3+5 crashes or misparses; also 2*-3). Write tests exposing both, fix evaluate() properly (unary minus must work after operators and open parens too), keep all passing.

