    tokens = re.findall(r"\d+\.?\d*|[+\-*/^()]", expr)
    out, ops = [], []

    def apply(op):
        if op == 'u-':
            out.append(-out.pop())
            return
        b, a = out.pop(), out.pop()
        out.append({'+': a+b, '-': a-b, '*': a*b, '/': a/b, '^': a**b}[op])

    def should_pop(incoming):
        top = ops[-1]
        if top == '(':
            return False
        p_top, p_in = _PREC[top], _PREC[incoming]
        return p_top > p_in or (p_top == p_in and incoming not in _RIGHT_ASSOC)

    prev = None
    for t in tokens:
        if t[0].isdigit():
            out.append(float(t))
        elif t == '(':
            ops.append(t)
        elif t == ')':
            while ops[-1] != '(':
                apply(ops.pop())
            ops.pop()
        else:
            # unary minus: at start of expression, after an operator,
            # or after an open paren (also handles chains like --3)
            if t == '-' and (prev is None or prev in '+-*/^('):
                ops.append('u-')
                prev = 'u-'
                continue
            while ops and should_pop(t):
                apply(ops.pop())
            ops.append(t)
        prev = t
    while ops:
        apply(ops.pop())
    return out[0]
